            Offers = product.Offers
                .OrderBy(o => o.Price)
                .ThenBy(o => o.SupplierId, StringComparer.Ordinal)
                .Select(o => new SupplierOfferDto { SupplierId = o.SupplierId, SupplierName = o.Supplier!.Name, Price = o.Price })
